"""When A on the tent's flag cell does not open the menu, retry its body.

g1190 2026-11-15: the hero's cliff-side camp answered A on the flag cell with
the bare map three times per recall and the recall gave up every month.
"""
from .test_hanjuku_chart_bot import _camp_frame

from docich.hanjuku_speedrun import hanjuku_policy as policy
from docich.hanjuku_speedrun.hanjuku.state.regions import flow as _flow
from docich.hanjuku_speedrun.hanjuku_screen import Screen
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import camp_body_target, own_camps


def memory():
    return {'chapter': 1, '_records': []}


def test_the_camp_body_is_not_the_flag_target():
    frame = _camp_frame()
    camp = own_camps(frame)[0]
    body = camp_body_target(frame, camp['target'])
    assert body and tuple(body) != tuple(camp['target'])


def test_two_failed_reopens_switch_the_retry_to_the_tent_body():
    frame = _camp_frame()
    mem = memory()
    tent = Screen([], None, '', kind='map', cursor=(27, 67))
    policy.camp_recall_step(tent, mem, frame)
    state = _flow(mem)['recall']
    assert state.get('camp_body') and state['camp_body'] != state['target']
    flag_target = list(state['target'])
    body = list(state['camp_body'])
    bare = Screen([], None, '', kind='map', cursor=(50, 50))
    # The A on the flag cell leaves the bare map; each reopen costs 3 observations.
    for _ in range(3):
        state['stage'] = 'menu'
        for _ in range(3):
            policy.camp_recall_step(bare, mem, frame)
    assert state['target'] == body and body != flag_target
    assert any(r.get('decision') == 'camp_enter_body_retry' for r in mem['_records'])


def test_the_body_retry_survives_the_next_to_camp_pass():
    # docich#4901 (ch10 v1317): to_camp re-detection restored the flag cell on
    # the very next pass, so every reopen pressed the dead cell again and the
    # recall looped camp_menu_not_opened until it gave up.
    frame = _camp_frame()
    mem = memory()
    tent = Screen([], None, '', kind='map', cursor=(27, 67))
    policy.camp_recall_step(tent, mem, frame)
    state = _flow(mem)['recall']
    bare = Screen([], None, '', kind='map', cursor=(50, 50))
    for _ in range(3):
        state['stage'] = 'menu'
        for _ in range(3):
            policy.camp_recall_step(bare, mem, frame)
    body = list(state['camp_body'])
    assert state['target'] == body and state['stage'] == 'to_camp'
    # The re-pick still sees the same tent but must keep the armed body cell.
    policy.camp_recall_step(bare, mem, frame)
    assert state['target'] == body and state['last_seen'] == body
